body_md:
We define a function $\phi : \mathbb{R}_+ \to \mathscr{U}$ as an \emph{admissible input signal}, if a unique solution to \eqref{eq:nominal system dynamics} exists given that input signal. The set of admissible control signals is defined as all possible admissible input signals $\mathbb{U} := \{\phi : \mathbb{R}_+ \to \mathscr{U}\}$.    









    We define a \emph{trajectory} $\varphi : \mathbb{R}_+ \times \mathbb{R}^n \times \mathbb{U} \to \mathbb{R}^n$ to be such that $x(t) = \varphi(t | x_0, \phi)$ satisfies \eqref{eq:nominal system dynamics} given initial state $x(0) = x_0 \in \mathbb{R}^n$ and input signal $u(t) = \phi(t) \in \mathbb{U}$, i.e.,
    \begin{equation*}
        \varphi(t | x_0, \phi) := x_0 + \int_0^t f(x(\tau), \phi(\tau)) \ \mathrm{d}\tau.
    \end{equation*}

    From the dynamics of \eqref{eq:nominal system dynamics}, we define a multifunction $F(t, x) := f(t, x, \mathscr{U}) : \mathbb{R}_+ \times \mathbb{R}^n \rightrightarrows \mathbb{R}^n$. This multifunction defines an \emph{ordinary differential inclusion} $\dot{x}(t) \in F(t, x(t))$, of which any instance of \eqref{eq:nominal system dynamics} is a part. We define the \emph{solution set} of this ordinary differential inclusion as follows:
    \begin{equation*}
        S_F (x_0) := \{ \varphi(\cdot | x_0, \phi) : x_0 \in \mathscr{X}_0, \phi \in \mathbb{U} \}.
    \end{equation*}

    Given a set of initial states $\mathscr{X}_0 \subseteq \mathbb{R}^n$, we define the \emph{forward reachable set} (FRS) at time $\tau \in \mathbb{R}_+$ as
    \begin{equation*}
    \begin{split}
        \mathbb{X}_\tau^\rightarrow (F, \mathscr{X}_0) &:= \bigcup_{x \in \mathscr{X}_0} \{x(\tau) : x \in S_F (x_0)\} \\
        &= \{\varphi(\tau | x_0, \phi) : x_0 \in \mathscr{X}_0, \phi \in \mathbb{U}\}. 
    \end{split}
    \end{equation*}

\label{assumption:nonlinear growth condition}
    For all $x \in \mathbb{R}^n$, $u \in \mathscr{U}$, $t_0 \leq t < \infty$
    \begin{equation*}
        \Vert h(t, x, u) \Vert \leq a(t) w(\Vert x \Vert, \Vert u \Vert) + b(t),
    \end{equation*}
    where $a, b$ are continuous and positive and $w$ is continuous, monotonic, nondecreasing and positive. In addition, $w$ is uniformly monotonically nondecreasing in $\Vert u \Vert$.

\label{thm:generalized Bihari inequality for controlled dynamical systems}
    Let $x(t)$ be a solution to the equation
    \begin{equation*}
        \dot{x} = h(t, x, u), \quad 0 \leq t_0 \leq t < \infty,
    \end{equation*}
    where $h(t, x, u) : [t_0, \infty) \times \mathbb{R}^n \times \mathscr{U} \to \mathbb{R}^n$ is continuous for $t_0 \leq t < \infty$, and $\mathscr{U} \subseteq \mathbb{R}^m$ is compact and satisfies $\max_{u \in \mathscr{U}} \Vert u \Vert = \delta$. Let Assumption~\ref{assumption:nonlinear growth condition} hold. Then,
    \begin{equation}\label{eq:Bihari inequality}
        \Vert x(t) \Vert \leq G^{-1} \left[ G\left( \Vert x(t_0) \Vert + \int_{t_0}^t b(\tau) \mathrm{d}\tau \right) + \int_{t_0}^t a(\tau) \mathrm{d}\tau \right],
    \end{equation}
    where the expression on the right-hand side is strictly increasing in $t$. In \eqref{eq:Bihari inequality}, we define
    \begin{equation*}\label{eq:big G integral}
        G(r) := \int_{r_0}^r \frac{\mathrm{d}s}{w(s, \delta)}, \quad r > 0, r_0 > 0,
    \end{equation*}
    for arbitrary $r_0 > 0$ and for all $t \geq t_0$ for which it holds that
    \begin{equation*}
        G\left( \Vert x(t_0) \Vert + \int_{t_0}^t b(\tau) \mathrm{d}\tau \right) + \int_{t_0}^t a(\tau) \mathrm{d}\tau \in \mathrm{dom}(G^{-1}).
    \end{equation*}

\label{corollary:generalized boundedness of trajectory deviation}
    For any $x_0 \in \mathscr{X}_0 \subseteq \mathbb{R}^n$, where $\mathscr{X}_0$ is compact, and any initial time $t_{\mathrm{init}} \in [t_0, \infty)$ and final time $t_f \in [t_{\mathrm{init}}, \infty)$, consider a trajectory $x(t)$ satisfying $x(t_{\mathrm{init}}) = x_0$ and $\dot{x}(t) = f(t, x(t), u(t))$, with $u(t) \in \mathbb{U}$. Consider a trajectory $\bar{x}(t)$ with $\bar{x}(t_{\mathrm{init}}) = x_0$ and $\dot{\bar{x}}(t) = f(t, \bar{x}(t), \bar{u}(t))$, such that $\bar{u}(t) \in \bar{\mathbb{U}}$ satisfies $\sup_{t \in [t_{\mathrm{init}}, t_f]} \Vert u(t) - \bar{u}(t) \Vert \leq \epsilon$. Let $\tilde{f} (t) := f(t, x(t), u(t)) - f(t, \bar{x}(t), \bar{u}(t))$, $\tilde{x}(t) := x(t) - \bar{x}(t)$, and $\tilde{u}(t) := u(t) - \bar{u}(t)$. Let the following bound hold for $t \in [t_{\mathrm{init}}, t_f]$, and for \emph{any} $x(t)$ and $\bar{x}(t)$ satisfying the previous hypotheses: $\Vert \tilde{f}(t) \Vert \leq \tilde{a}(t) \tilde{w}(\Vert \tilde{x}(t) \Vert, \Vert \tilde{u}(t) \Vert) + \tilde{b}(t)$ with $\tilde{a}, \tilde{b}, \tilde{w}$ satisfying the assumptions given in Assumption~\ref{assumption:nonlinear growth condition}. Then, $\tilde{x}(t)$ satisfies
        \begin{equation*}\label{eq:Bihari inequality deviation}
            \Vert \tilde{x}(t) \Vert \leq G^{-1} \left[ G\left( \int_{t_0}^t \tilde{b}(\tau) \mathrm{d}\tau \right) + \int_{t_0}^t \tilde{a}(\tau) \mathrm{d}\tau \right] =: \eta(t, \epsilon)
        \end{equation*}
        for all $t \in [t_{\mathrm{init}}, t_f]$.

\label{corollary:generalized boundedness of trajectory deviation with changed initial conditions}
    For any $x_0 \in \mathscr{X}_0 \subseteq \mathbb{R}^n$, where $\mathscr{X}_0$ is compact, and any initial time $t_{\mathrm{init}} \in [t_0, \infty)$ and final time $t_f \in [t_{\mathrm{init}}, \infty)$, consider a trajectory $x(t)$ satisfying $x(t_{\mathrm{init}}) = x_0$ and $\dot{x}(t) = f(t, x(t), u(t))$, with $u(t) \in \mathbb{U}$. Consider a trajectory $\bar{x}(t)$ with $\bar{x}(t_{\mathrm{init}}) = \bar{x}_0$, where $\bar{x}_0 \in \bar{\mathscr{X}}_0 \subseteq \mathbb{R}^n$, and $\dot{\bar{x}}(t) = f(t, \bar{x}(t), \bar{u}(t))$, such that $\bar{u}(t) \in \bar{\mathbb{U}}$ satisfies $\sup_{t \in [t_{\mathrm{init}}, t_f]} \Vert u(t) - \bar{u}(t) \Vert \leq \epsilon$. Let $\tilde{f} (t) := f(t, x(t), u(t)) - f(t, \bar{x}(t), \bar{u}(t))$, $\tilde{x}(t) := x(t) - \bar{x}(t)$, and $\tilde{u}(t) := u(t) - \bar{u}(t)$. Let $d_{\text{H}} (\mathscr{X}_0, \bar{\mathscr{X}}_0) \leq \kappa$. Let the following bound hold for $t \in [t_{\mathrm{init}}, t_f]$, and for \emph{any} $x(t)$ and $\bar{x}(t)$ satisfying the previous hypotheses: $\Vert \tilde{f}(t) \Vert \leq \tilde{a}(t) \tilde{w}(\Vert \tilde{x}(t) \Vert, \Vert \tilde{u}(t) \Vert) + \tilde{b}(t)$ with $\tilde{a}, \tilde{b}, \tilde{w}$ satisfying the assumptions given in Assumption~\ref{assumption:nonlinear growth condition}. Then, $\tilde{x}(t)$ satisfies
        \begin{equation*}\label{eq:Bihari inequality deviation}
        \begin{split}
            \Vert \tilde{x}(t) \Vert &\leq G^{-1} \left[ G\left( \kappa + \int_{t_0}^t \tilde{b}(\tau) \mathrm{d}\tau \right) + \int_{t_0}^t \tilde{a}(\tau) \mathrm{d}\tau \right] \\
            &=: \eta(t, \epsilon, \kappa)
        \end{split}
        \end{equation*}
        for all $t \in [t_{\mathrm{init}}, t_f]$.

\label{assumption:off-nominal dynamics norm bound}
    For all $x \in \mathbb{R}^n$, $u \in \mathscr{U}$, $t_0 \leq t < \infty$, we have
    \begin{equation*}
        \Vert g(t, x, u) - f(t, x, u) \Vert \leq \gamma(t),
    \end{equation*}
    where $\gamma$ is a positive, continuous function on $[t_0, \infty)$.

\label{lm:impaired dynamics norm bound}
    Let Assumption~\ref{assumption:off-nominal dynamics norm bound} hold true. Consider functions $\bar{a}, \bar{b}, \bar{w}$, in the sense of Assumption~\ref{assumption:nonlinear growth condition}, which apply to the following dynamics
     \begin{equation*}
        \dot{\tilde{x}}(t) = f(t, x(t) + \tilde{x}(t), u(t) + \tilde{u}(t)) - f(t, x(t), u(t)), \quad \tilde{x}(t_0) = 0.
    \end{equation*}
    We consider nominal control signal $u \in \mathbb{U}_\epsilon$, and an off-nominal control signal of the form $(u + \bar{u}) \in \mathbb{U}$ are such that $\sup_{\bar{u}(t), t \in [t_0, \infty)} \Vert \bar{u}(t) \Vert \leq \epsilon$.

    In addition, consider the following off-nominal trajectory deviation dynamics:
    \begin{equation*}
        \dot{\hat{x}}(t) = g(t, x(t) + \hat{x}(t), u(t) + \hat{u}(t)) - f(t, x(t), u(t)), \quad \hat{x}(t_0) = 0.
    \end{equation*}
    Control signals $u$ and $\hat{u}$ are defined similarly to those of the nominal dynamics. We have a nominal control signal $u \in \mathbb{U}_\epsilon$, and an off-nominal control signal of the form $(u + \hat{u}) \in \mathbb{U}$ such that $\sup_{\hat{u}(t), t \in [t_0, \infty)} \Vert \hat{u}(t) \Vert \leq \epsilon$.

    We define $\hat{b}(t) := \tilde{b}(t) + \gamma(t)$. We have that $\Vert \tilde{x}(t) \Vert \leq \eta(t, \epsilon)$, where $\eta(t, \epsilon)$ is obtained as in Corollary~\ref{corollary:generalized boundedness of trajectory deviation} with $\tilde{a} = \bar{a}$, $\tilde{b} = \hat{b}$, $\tilde{w} = \bar{w}$.

\label{def:hyperrectangular nonlinear growth bound}
    We say that a function $h : [t_0, \infty) \times \mathbb{R}^n \times \mathscr{U} \to \mathbb{R}^n$ has \emph{$(a_i, b_i, w_i)$-bounded growth} if for all $x \in \mathbb{R}^n$, $u \in \mathscr{U}$, $t_0 \leq t < \infty$, the following inequality holds:
    \begin{equation*}
        | h_i (t, x, u) | \leq a_i (t) w_i (| x_i |, \Vert u \Vert) + b_i (t),
    \end{equation*}
    for each $i \in \{1, \ldots, n\}$,
    where $a_i, b_i$ are continuous and positive and $w_i$ is continuous, monotonic, nondecreasing and positive in both of its arguments.

\label{lemma:hyperrectangular generalized boundedness of trajectory deviation}
    For any $x_0 \in \mathscr{X}_0 \subseteq \mathbb{R}^n$, where $\mathscr{X}_0$ is compact, and any initial time $t_{\mathrm{init}} \in [t_0, \infty)$ and final time $t_f \in [t_{\mathrm{init}}, \infty)$, consider a trajectory $x(t)$ satisfying $x(t_{\mathrm{init}}) = x_0$ and $\dot{x}(t) = f(t, x(t), u(t))$, with $u(t) \in \mathbb{U}$. Consider a trajectory $\bar{x}(t)$ with $\bar{x}(t_{\mathrm{init}}) = x_0$ and $\dot{\bar{x}}(t) = f(t, \bar{x}(t), \bar{u}(t))$, such that $\bar{u}(t) \in \bar{\mathbb{U}}$ satisfies $\sup_{t \in [t_{\mathrm{init}}, t_f]} \Vert u(t) - \bar{u}(t) \Vert \leq \epsilon$. Let $\tilde{f} (t) := f(t, x(t), u(t)) - f(t, \bar{x}(t), \bar{u}(t))$, $\tilde{x}(t) := x(t) - \bar{x}(t)$, and $\tilde{u}(t) := u(t) - \bar{u}(t)$. Let $\tilde{f}$ be of $(\tilde{a}_i, \tilde{b}_i, \tilde{w}_i)$-bounded growth for $t \in [t_{\mathrm{init}}, t_f]$. Then, $\tilde{x}(t)$ satisfies
        \begin{equation}\label{eq:Bihari inequality deviation componentwise}
            | \tilde{x}_i (t) | \leq G_i^{-1} \left[ G_i\left( \int_{t_0}^t \tilde{b}_i (\tau) \mathrm{d}\tau \right) + \int_{t_0}^t \tilde{a}_i (\tau) \mathrm{d}\tau \right] =: \eta_i (t, \epsilon)
        \end{equation}
        for each $i \in \{1, \ldots, n\}$ and for all $t \in [t_{\mathrm{init}}, t_f]$, where the $G_i$ are defined as $G$ in Theorem~\ref{thm:generalized Bihari inequality for controlled dynamical systems}.

\label{def:hyperrectangular fattening}
    Given a compact set $X \subseteq \mathbb{R}^n$, a hyperrectangular fattening by $\rho \in \mathbb{R}^n$ with $\rho \succeq 0$ is defined as:
    \begin{equation*}
        X_{\boxplus \rho} := \bigcup_{x \in X} \left[ \{x\} \oplus \left( \operatorname*{\scalerel*{\times}{\sum}}_{i =  1}^n [-\rho_i, \rho_i] \right) \right].
    \end{equation*}

\label{def:hyperrectangular distance}
    Given two compact sets $A, B \subseteq \mathbb{R}^n$, we denote by $d_{\mathrm{R}} (A, B)$ their \emph{hyperrectangular distance}, defined as follows.

    On each Cartesian axis $i = 1, \ldots, n$, consider each point $x \in A$ and $y \in B$. We denote by $h_i (x, B)$ the following:
    \begin{equation*}
    \begin{split}
        h_i (x, B) = \min \{ |x_i - y_i| : y \in B\}.
    \end{split}
    \end{equation*}
    If $B = \emptyset$, we say $h_i (x, B) = \infty$.


    We denote the hyperrectangular distance as $d_{\mathrm{R}, i} (A, B) = \max \{ \max_{x \in A} h_i (x, B), \max_{y \in B} h_i (y, A) \}$. Combining each component, we define
    \begin{equation*}
        d_{\mathrm{R}} (A, B) := \begin{bmatrix} d_{\mathrm{R}, 1} (A, B) & \cdots & d_{\mathrm{R}, n} (A, B) \end{bmatrix}^\mathsf{T}.
    \end{equation*}

\label{def:Staicu function space}
    Let $S$ be a function space defined as
    \begin{equation*}
        S := \left\{x \in C([0, \infty), \mathbb{R}^n) : \dot{x} \in L_{\mathrm{loc}}^1 ([0, \infty), \mathbb{R}^n)\right\},
    \end{equation*}
    endowed with distance metric $d_S$ defined as
    \begin{equation}
        d_S (x, y) := \Vert x(0) - y(0) \Vert + \sum_{k = 1}^\infty \frac{1}{2^k} \frac{\int_0^k \Vert \dot{x}(t) - \dot{y}(t) \Vert \ \mathrm{d}t}{1 + \int_0^k \Vert \dot{x}(t) - \dot{y}(t) \Vert \ \mathrm{d}t}.
    \end{equation}

\label{lemma:path-connectedness of solution set}
    Consider a differential inclusion
    \begin{equation*}
    \begin{split}
        \dot{x}(t) &\in F(t, x(t)), \quad \text{a.e.} \ t \in [0,T], \\
        x(0) &= x_0 \in \mathbb{R}^n,
    \end{split}
    \end{equation*}
    where $F : [0, \infty) \times \mathbb{R}^n \rightrightarrows \mathbb{R}^n$ is a compact-valued multifunction.
    Let $F(t, x)$ be path-connected for all $(t, x) \in \mathbb{R}^n \times \mathbb{R}^n$, and let $F(t, x)$ be continuous and Lipschitz in $t$ and $x$.
    Then for any $x_0 \in \mathbb{R}^n$, the set of solutions
    \begin{equation*}
    \begin{split}
        S_F(x_0) := \{x \in S : &x(0) = x_0,  \\
        &\dot{x}(t) \in F(t, x(t)) \ \text{a.e.} \ t \in [0, \infty)\},
    \end{split}
    \end{equation*}
    is path-connected in the space $(S, d_S)$.

Since the conditions of Lemma~\ref{lemma:path-connectedness of solution set} on $F$ will be required throughout this work, we will look at the applicability of these conditions to commonly encountered classes of dynamical systems. We list two here:
    \begin{enumerate}
        \par\hangindent 40\p@ \emph{Affine-in-control systems}: Consider functions $g : [0, \infty) \times \mathbb{R}^n \to \mathbb{R}^n$ and $h : [0, \infty) \times \mathbb{R}^n \to \mathbb{R}^{n \times m}$ that form the following differential equation:
        \begin{equation*}
            \dot{x}(t) = g (t, x(t)) + h (t, x(t)) u(t).
        \end{equation*}
        From this system, we can introduce a differential inclusion defined by a multifunction
        \begin{equation*}
            F(t, x) := \{g (t, x)\} \oplus h (t, x) \mathscr{U},
        \end{equation*}
        where $\mathscr{U} \subseteq \mathbb{R}^m$ is nonempty, compact, and path-connected. If $g$ and $h$ are continuous and Lipschitz in their arguments, then $F$ will satisfy conditions of Lemma~\ref{lemma:path-connectedness of solution set}.
        \par\hangindent 40\p@ \emph{General nonlinear systems}: For a dynamical system of the form of \eqref{eq:nominal system dynamics}, a sufficient condition for $F(t, x) := f(t, x, \mathscr{U})$ to satisfy the condition of Lemma~\ref{lemma:path-connectedness of solution set}, is for $\mathscr{U}$ to be nonempty, compact, and path-connected, and $f(t, x)$ to be continuous and Lipschitz in $t$ and $x$.
    \end{enumerate}
    Relaxations to the conditions of Lemma~\ref{lemma:path-connectedness of solution set} are presented in Appendix~\ref{app:generalizations}.

\label{prop:solution set values continuum}
    For a differential inclusion
    \begin{equation*}
    \begin{split}
        \dot{x}(t) &\in F(t, x(t)), \quad \text{a.e.} \ t \in [0,T], \\
        x(0) &= x_0 \in \mathbb{R}^n,
    \end{split}
    \end{equation*}
    where $F : [0, \infty) \times \mathbb{R}^n \rightrightarrows \mathbb{R}^n$ is a compact-valued multifunction. Let $F$ satisfy the hypotheses of Lemma~\ref{lemma:path-connectedness of solution set}.

    Then, for any $x_0 \in \mathbb{R}^n$, the solution set $S_F (x_0)$ is a path-connected \emph{continuum} in $S$, i.e., a nonempty, compact, path-connected subset of $S$. In addition, the sets $S_F^t (x_0)$ are path-connected continua in $\mathbb{R}^n$ for all $t \in [0, \infty)$.

The fact that $S_F (x_0)$ is a nonempty compact subset of $S$ follows from \cite[Thm.~5.1, p.~228]{Tolstonogov1986}. It is clear that the values of $S_F (x_0)$ will be nonempty, since $\# S_F (x_0) > 0$. Given some $t \in [0, \infty)$, we define a functional $E_t : S \to \mathbb{R}^n$ as $E_t (x) := x(t)$. If $E_t$ can be shown to be continuous, then $E_t$ is a \emph{preserving} map in the sense of \cite[p.~21]{Gerlits2004}, i.e., the image $E_t (S_F(x_0)) = S_F^t (x_0) \subseteq \mathbb{R}^n$ preserves the compactness and path-connectedness properties of $S_F(x_0)$. We proceed to show that $E_t$ is indeed a continuous linear functional.

    We require linearity to show that $E_t$ is uniformly continuous on all of $S$. To show that $E_t$ is linear, consider two functionals $x, y \in S$, and a scalar $\alpha \in \mathbb{R}$. We clearly find
    \begin{equation*}
    \begin{split}
        E_t (x + y) &= (x + y)(t) = x(t) + y(t) = E_t (x) + E_t (y), \\
        E_t (\alpha x) &= (\alpha x)(t) = \alpha x(t) = \alpha E_t (x).
    \end{split}
    \end{equation*}

    If $E_t$ is linear, by \cite[Thm.~1.1, p.~54]{Taylor1986} it suffices to show that $E_t$ is continuous at any one $y \in S$. Continuity of the functional is shown next by using the $\delta$--$\epsilon$ criterion \cite[p.~52]{Taylor1986}.

    We proceed to show that for each $\epsilon > 0$, there exists some $\epsilon' > 0$ such that $\Vert E_t (x) - E_t (y) \Vert < \epsilon$ for all $x \in S$ such that $d_S (x, y) < \epsilon'$. To this end, let us define $a_k := \int_0^k \Vert \dot{x}(t) - \dot{y}(t) \Vert \ \mathrm{d}t$. By definition of the solution set, we have for any $x, y \in S_F (x_0)$:
    \begin{equation*}
    \begin{split}
        d_S (x, y) &= \Vert x(0) - y(0) \Vert + \sum_{k = 1}^\infty \frac{1}{2^k} \frac{a_k}{1 + a_k} \\
        &= \sum_{k = 1}^\infty \frac{1}{2^k} \frac{a_k}{1 + a_k} = \sum_{k = 1}^\infty \frac{1}{2^k} \frac{1}{1 + a_k^{-1}},        
    \end{split}
    \end{equation*}
    since $x(0) = y(0) = x_0$.

    We know by path-connectedness of $S_F (x_0)$ that for any $x \in S_F (x_0)$, given some $\epsilon' > 0$, there exists $y \in S_F (x_0) \setminus \{x\}$ such that $d_S (x, y) < \epsilon'$. In general, we can upper-bound the difference between values of $x$ and $y$ at time $t$ as follows:
    \begin{equation*}
    \begin{split}
        \Vert x(t) - y(t) \Vert &= \left\Vert x(0) + \int_0^t \dot{x} (s) \ \mathrm{d}s - y(0) - \int_0^t \dot{y} (s) \ \mathrm{d}s \right\Vert \\
        &= \left\Vert \int_0^t \dot{x} (s) - \dot{y} (s) \ \mathrm{d}s \right\Vert \leq \int_0^t \Vert \dot{x}(s) - \dot{y}(s) \Vert \ \mathrm{d}s,
    \end{split}
    \end{equation*}
    which follows from Jensen's inequality \cite[p.~109]{Folland1999}.

    Given some $\epsilon > 0$ and $t \in (0, \infty)$, let $K := \lceil t \rceil \in \mathbb{N}$. Since $\int_0^t \Vert \dot{x}(s) - \dot{y}(s) \Vert \ \mathrm{d}s < \epsilon$ implies $d(x(t), y(t)) < \epsilon$, it suffices to show that there exists some $\epsilon' > 0$, such that any $y \in S_F (x_0) \setminus \{x\}$ that satisfies $d_S (x, y) < \epsilon'$ yields $\int_0^t \Vert \dot{x}(s) - \dot{y}(s) \Vert \ \mathrm{d}s < \epsilon$. We choose $\epsilon'$ as follows:
    \begin{equation*}
    \begin{split}
        d_S (x, y) &= \sum_{k = 1}^\infty \frac{1}{2^k} \frac{1}{1 + a_k^{-1}} \\
        &\geq \left( \sum_{k = 1}^K \frac{1}{2^k} \frac{1}{1 + \epsilon^{-1}} \right) + \left( \sum_{k = K+1}^\infty \frac{1}{2^k} \frac{1}{1 + a_k^{-1}} \right) \\
        &\geq \sum_{k = 1}^K \frac{1}{2^k} \frac{1}{1 + \epsilon^{-1}} =: \epsilon'(t, \epsilon).
    \end{split}
    \end{equation*}
    We may evaluate $\epsilon'(t, \epsilon)$ as
    \begin{equation*}
        \epsilon'(t, \epsilon) = \frac{(1 - 2^{-K}) \epsilon}{1 + \epsilon} > 0.
    \end{equation*}
    If we consider $y \in S_F (x_0) \setminus \{x\}$ such that $d_S (x, y) < \epsilon'(t, \epsilon)$, we have therefore shown that we obtain $d(x(t), y(t)) < \epsilon$; at least one such $y$ exists by path-connectedness of $S_F (x_0)$. We thus proved continuity of $E_t$.

    Having shown that $E_t$ is a continuous (linear) operator (and therefore a preserving map), we have proven that $E_t (S_F(x_0))$ is a path-connected continuum for all $t \in [0, \infty)$ and $x_0 \in \mathbb{R}^n$.

















\nobreak\hfill$\square$

\label{lemma:connectedness of reachable set}
    For a differential inclusion
    \begin{equation*}
    \begin{split}
        \dot{x}(t) &\in F(t, x(t)), \quad \text{a.e.} \ t \in [0,T], \\
        x(0) &= x_0 \in \mathbb{R}^n,
    \end{split}
    \end{equation*}
    where $F : [0, \infty) \times \mathbb{R}^n \rightrightarrows \mathbb{R}^n$ satisfies all conditions listed in Proposition~\ref{prop:solution set values continuum}, given a path-connected continuum $\mathscr{X}_0 \subseteq \mathbb{R}^n$, reachable set $\mathbb{X}_t^\rightarrow (F, \mathscr{X}_0)$ is path-connected for all $t \in [0, \infty)$.

\label{thm:reachable set guaranteed underapproximation impaired general}
    Let $f : [0, \infty) \times \mathbb{R}^n \times \mathscr{U} \to \mathbb{R}^n$, $g : [0, \infty) \times \mathbb{R}^n \times \mathscr{V} \to \mathbb{R}^n$, where $\mathscr{U}, \mathscr{V} \subseteq \mathbb{R}^m$ are such that $d_{\mathrm{R}} (\mathscr{U}, \mathscr{V}) \preceq \epsilon$. Let $G (t, x) = g(t, x, \mathscr{V})$ and $F (t, x) = f(t, x, \mathscr{U})$, and let $\mathscr{X}_0 \subseteq \mathbb{R}^n$, the set of initial states, and initial time $t_0 \in \mathbb{R}_+$ be given. Let $\mathscr{X}_0$, $f, g$, and $\mathscr{U}, \mathscr{V}$ satisfy the conditions of Lemma~\ref{lemma:connectedness of reachable set}. Let the hypotheses of Lemma~\ref{lemma:hyperrectangular generalized boundedness of trajectory deviation} be satisfied with $\bar{\mathscr{U}} = \mathscr{V}$, $t_{\mathrm{init}} = t_0$, and $t_f > t_{\mathrm{init}}$. Let $\eta(t, \epsilon)$ be obtained as in Lemma~\ref{lemma:hyperrectangular generalized boundedness of trajectory deviation}. Then:
    \begin{enumerate}[label=(\roman*), wide, labelwidth=!, labelindent=0pt]
        \par\hangindent 40\p@ For each $x_0 \in \mathscr{X}_0$ there exists a trajectory $x(t)$ emanating from $x (t_0) = x_0$ with $\dot{x}(t) \in F(t, x(t))$ and a trajectory $y (t)$ satisfying $y (t_0) = x_0$ and $\dot{y} (t) \in G (t, y(t))$ such that $|x(t) - y(t)| \preceq \eta (t, \epsilon)$ for all $t \in [t_0, t_f]$;
        \par\hangindent 40\p@ Let $T \in [0, t_f - t_0]$, and let $\eta^* = \eta(t_0 + T, \epsilon)$. For all $t \in [t_0, t_0 + T]$, $d_{\mathrm{R}} [\mathbb{X}^\rightarrow_t (G, \mathscr{X}_0), \mathbb{X}^\rightarrow_t (F, \mathscr{X}_0)] \preceq \eta^*$;
        \par\hangindent 40\p@ For all $t \in [t_0, t_0 + T]$, \begin{equation*}
            \mathbb{X}^\rightarrow_t (F, \mathscr{X}_0) \setminus (\partial \mathbb{X}^\rightarrow_t (F, \mathscr{X}_0))_{\boxplus \eta^*} \subseteq \mathbb{X}^\rightarrow_t (G, \mathscr{X}_0).
        \end{equation*}
    \end{enumerate}

\label{cor:reachable set guaranteed innerapproximation impaired general changed initial conditions}
    Let the hypotheses of Theorem~\ref{thm:reachable set guaranteed underapproximation impaired general} hold. In addition, let there be an off-nominal set of initial conditions $\bar{\mathscr{X}}_0$ that is nonempty, closed, and connected, such that $d_{\text{H}} (\mathscr{X}_0, \bar{\mathscr{X}}_0) \leq \kappa$. Define $\eta(t, \epsilon, \kappa)$ as in Corollary~\ref{corollary:generalized boundedness of trajectory deviation with changed initial conditions}. Then:
    \begin{enumerate}[label=(\roman*), wide, labelwidth=!, labelindent=0pt]
        \par\hangindent 40\p@ For each $x_0 \in \mathscr{X}_0$ there exists a trajectory $x(t)$ emanating from $x (t_0) = x_0$ with $\dot{x}(t) \in F(t, x(t))$ and a trajectory $y (t)$ satisfying $y (t_0) = x_0'$, for some $x_0' \in \{x_0\}_{+\kappa} \cap \bar{\mathscr{X}}_0$, and $\dot{y} (t) \in G (t, y(t))$ such that $|x(t) - y(t)| \preceq \eta (t, \epsilon, \kappa)$ for all $t \in [t_0, t_f]$;
        \par\hangindent 40\p@ Let $T \in [0, t_f - t_0]$, and let $\eta^{**} = \eta(t_0 + T, \epsilon, \kappa)$. For all $t \in [t_0, t_0 + T]$, $d_{\mathrm{R}} [\mathbb{X}^\rightarrow_t (G, \bar{\mathscr{X}}_0), \mathbb{X}^\rightarrow_t (F, \mathscr{X}_0)] \preceq \eta^{**}$;
        \par\hangindent 40\p@ For all $t \in [t_0, t_0 + T]$, \begin{equation*}
            \mathbb{X}^\rightarrow_t (F, \mathscr{X}_0) \setminus (\partial \mathbb{X}^\rightarrow_t (F, \mathscr{X}_0))_{\boxplus \eta^{**}} \subseteq \mathbb{X}^\rightarrow_t (G, \bar{\mathscr{X}}_0).
        \end{equation*}
    \end{enumerate}

\label{cor:reachable set guaranteed overapproximation impaired general}
    Let the hypotheses of Theorem~\ref{thm:reachable set guaranteed underapproximation impaired general} and Corollary~\ref{cor:reachable set guaranteed innerapproximation impaired general changed initial conditions} hold. Then:
    \begin{enumerate}[label=(\roman*)]
        \par\hangindent 40\p@ For each $x_0 \in \mathscr{X}_0$ there exists a trajectory $x(t)$ emanating from $x (t_0) = x_0$ with $\dot{x}(t) \in F(t, x(t))$, and a trajectory $y (t)$ satisfying $y (t_0) = y_0$ with $y_0 \in \bar{\mathscr{X}}_0$ such that $\Vert x_0 - y_0 \Vert \leq \kappa$ and $\dot{y} (t) \in G (t, y (t))$, such that $|x(t) - y (t) | \preceq \eta(t, 2\delta + \epsilon, \kappa)$ for all $t \in [t_0, t_f]$ and $i = 1, \ldots, n$, where $\delta := \max_{u \in \mathscr{U}} \Vert u \Vert$;
        \par\hangindent 40\p@ For all $t \in [t_0, t_f]$, $d_{\mathrm{R}} [\mathbb{X}^\rightarrow_t (G, \bar{\mathscr{X}}_0), \mathbb{X}^\rightarrow_t (F, \mathscr{X}_0)] \preceq \eta (t_f, 2\delta + \epsilon, \kappa)$;
        \par\hangindent 40\p@ For all $t \in [t_0, t_f]$, \begin{equation*}
            \mathbb{X}^\rightarrow_t (G, \bar{\mathscr{X}}_0) \subseteq (\mathbb{X}^\rightarrow_t (F, \mathscr{X}_0))_{\boxplus \eta(t_f, 2\delta + \epsilon, \kappa)}.
        \end{equation*}
    \end{enumerate}

\begin{enumerate}[label=(\roman*), wide, labelwidth=!, labelindent=0pt]
    \par\hangindent 40\p@ This claim follows from Lemma~\ref{lm:impaired dynamics norm bound}, where we have used the following inequality:
    \begin{equation*}
        \Vert u(t) - v(t) \Vert \leq \Vert u(t) \Vert + \Vert v(t) \Vert \leq \delta + \delta + d_{\mathrm{H}} (\mathscr{U}, \mathscr{V}) \leq 2\delta + \epsilon,
    \end{equation*}
    which follows from the triangle inequality, as well as the definition of the Hausdorff distance.
    \par\hangindent 40\p@ This fact follows directly from Lemma~\ref{lm:impaired dynamics norm bound}.
    \par\hangindent 40\p@ The proof here is similar to that of Theorem~\ref{thm:reachable set guaranteed underapproximation impaired general}(iii), where we consider that any point in $A$ has a counterpart in $B$ that is distance $ \eta(t_f, 2\delta + \epsilon)$ away. The proof is immediate from this consideration and Lemma~\ref{lemma:hyperrectangular generalized boundedness of trajectory deviation}.
\end{enumerate}
